@main
struct DirectModelTestingRunner {
    @MainActor static func main() async {
        _ = NSApplication.shared
        NSApp.setActivationPolicy(.prohibited)
        guard Bundle.main.bundleIdentifier == "im.some.xomo.modelprobe",
              NSLocalizedString("imageEditor.export.scope.slice", comment: "") != "imageEditor.export.scope.slice"
        else { fputs("Missing native bundle resources\n", stderr); exit(3) }
        for path in CommandLine.arguments[1...2] {
            guard dlopen(path, RTLD_NOW | RTLD_GLOBAL) != nil else {
                fputs(String(cString: dlerror()) + "\n", stderr)
                exit(2)
            }
        }
        var arguments = Testing.__CommandLineArguments_v0()
        arguments.parallel = false
        arguments.filter = [CommandLine.arguments[3]]
        arguments.eventStreamOutputPath = CommandLine.arguments[4]
        arguments.listTests = CommandLine.arguments.contains("--list")
        let code: CInt = await Testing.__swiftPMEntryPoint(passing: arguments)
        exit(code)
    }
}

