def source_sha(root)
  contract = JSON.parse(File.read(File.join(root,'docs/reviews/2026-10-04-rc1727-test-build.json')))
  pairs = contract.fetch('source_inputs').fetch('paths').map { |p| [p,Digest::SHA256.file(File.join(root,p)).hexdigest] }
  Digest::SHA256.hexdigest(JSON.generate(pairs))
end
