    records=File.readlines(events_path).map { |line| JSON.parse(line) }
    tests=records.select { |r| r['kind']=='test' && r.dig('payload','kind')=='function' }.map { |r| r.fetch('payload') }
    events=records.select { |r| r['kind']=='event' }.map { |r| r.fetch('payload') }
    canonical=->(id) { id.split('/')[0..1].join('/') }
    function_ids=tests.map { |t| t.fetch('id') }
    begun=events.select { |e| e['kind']=='testStarted' && function_ids.include?(e['testID']) }.map { |e| canonical.call(e['testID']) }
    ended=events.select { |e| e['kind']=='testEnded' && function_ids.include?(e['testID']) }.map { |e| canonical.call(e['testID']) }
    issues=events.select { |e| e['kind']=='issueRecorded' }
    skipped=events.select { |e| e['kind'].downcase.include?('skip') }
    cases=events.select { |e| e['kind']=='testCaseStarted' }
    case_ends=events.select { |e| e['kind']=='testCaseEnded' }
    missing_cases=tests.select { |t| t['isParameterized'] && !cases.any? { |e| e['testID']==t['id'] } }.map { |t| t['id'] }
    passed=status.success? && begun.sort==expected.sort && ended.sort==expected.sort && issues.empty? && skipped.empty? && missing_cases.empty? && cases.size==case_ends.size && events.count { |e| e['kind']=='runEnded' }==1
    row={'suite'=>suite,'command'=>command,'exit'=>status.exitstatus,'seconds'=>(Process.clock_gettime(Process::CLOCK_MONOTONIC)-started).round(3),'expected_methods'=>expected.size,'started_methods'=>begun.size,'ended_methods'=>ended.size,'missing'=>expected-ended,'unexpected'=>ended-expected,'parameter_case_starts'=>cases.size,'parameter_case_ends'=>case_ends.size,'parameter_methods_without_cases'=>missing_cases,'issue_count'=>issues.size,'skip_count'=>skipped.size,'passed'=>passed,'events_sha256'=>Digest::SHA256.file(events_path).hexdigest}
    report['results']<<row
