    puts JSON.generate(row.reject { |k,v| k=='command' })
    $stdout.flush
    raise 'Coverage or execution failed' unless passed
  end
  report['source_after_sha256']=source_sha(root)
  report['passed']=report['source_after_sha256']==report['source_sha256'] && report['results'].all? { |r| r['passed'] }
